#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve(){
    int n;
    cin >> n;
    
    int N = 3 * n;
    
    vector<int>v(N);
    for(int &x : v){
        cin >> x;
    }
    
    sort(v.rbegin(), v.rend());
    
    vector<ll> pref(N + 1, 0);
    
    for(int i = 0; i < N; i++){
        pref[i + 1] = pref[i] + v[i];
    }
    auto value = [&](int A, int B) -> ll{
        int mid = A + 2 * B;
        int end = 3 * n - 2 * A - B;
        
        ll x = 6ll * pref[A] 
                + 4ll * (pref[mid] - pref[A])
                + 3ll * (pref[end] - pref[mid]);
        return x;
    };
    
    ll ans = 0; 
    
    for(int a = 0; a <= n; a++){
        int lo = 0;
        int hi = n - a;

        while(hi - lo > 5){
            int m1 = lo + (hi - lo) / 3;
            int m2 = hi - (hi - lo) / 3;
            
            if(value(a, m1) < value(a, m2)){
                lo = m1 + 1;
            }else{
                hi = m2 - 1;
            }
        }
        for(int b = lo; b <= hi; b++){
            ans = max(ans, value(a, b));
        }
        
    }
    cout << ans << endl;
    
    
}

int main() {
	// your code goes here
	int t = 1;
	cin >> t;
	
	while(t--){
	    solve();
	}
	

}
